content.text:
go: added github.com/Elven9/pi-agent/go v0.1.0
	github.com/Elven9/pi-agent/go v0.1.0 // indirect
package sessionparser // import "github.com/Elven9/pi-agent/go/pkg/session-parser"

Package sessionparser reads pi session files (JSONL) written by pi with the
pi-agent extensions.

A session file has one JSON object per line. The first line is the Header;
every other line is an entry that pi links into a tree by id and parentId.
Session.Branch is the current branch: from the root to the last entry in the
file. Two versions describe a file:

  - Header.Version is pi's session format. pi owns it and migrates older files
    when it loads them; this package reads format SupportedFormatVersion only.
  - Metadata.AgentVersion is the pi-agent release that wrote the file, from its
    "pi-agent.session-version" custom entries.

Parse reads every entry's envelope and keeps the whole line in Entry.Raw.
The data is read in groups, each on its own:

  - Session.Metadata: header fields, pi-agent version, tags, name, models,
    errors.
  - Session.ToolCalls: tool calls with their results and tool-ref handles.
  - Session.Metrics: the pi-agent.metrics totals and samples.
  - Session.Subagents: subagents started and their results.

Values a file doesn't have are nil. Parsing is strict: an invalid line
fails Parse with a *LineError, and an invalid entry fails its group with an
*EntryError (or an *UnsupportedVersionError for a pi-agent payload version this
package doesn't know).

CONSTANTS

const (
	// TypeSession is the header's type.
	TypeSession = "session"
	// TypeMessage is a conversation message (user, assistant, tool result, ...).
	TypeMessage = "message"
	// TypeModelChange records a switch of model.
	TypeModelChange = "model_change"
	// TypeSessionInfo holds the session's display name.
	TypeSessionInfo = "session_info"
	// TypeCustom is an extension's entry, never model context; its payload is "data".
	TypeCustom = "custom"
	// TypeCustomMessage is an extension's message, sent to the model; its payload is "details".
	TypeCustomMessage = "custom_message"
)
    pi's entry types.

const (
	// CustomTypeSessionVersion: the pi-agent release that wrote the entries after it.
	CustomTypeSessionVersion = "pi-agent.session-version"
	// CustomTypeTags: the session's tags; the last one in the file wins.
	CustomTypeTags = "pi-agent.tags"
	// CustomTypeError: an extension could not run and pi shut down.
	CustomTypeError = "pi-agent.error"
	// CustomTypeMetrics: session metrics, cumulative along the branch.
	CustomTypeMetrics = "pi-agent.metrics"
	// CustomTypeSubagentStart: a subagent was started.
	CustomTypeSubagentStart = "subagent-start"
	// CustomTypeSubagentEnd: a subagent result recorded at session end, not yet delivered.
	CustomTypeSubagentEnd = "subagent-end"
	// CustomTypeSubagentResult: a subagent result delivered to the model (custom_message).
	CustomTypeSubagentResult = "subagent-result"
)
    pi-agent's custom types (src/shared/protocol.ts, src/subagent/protocol.ts).

const (
	SubagentOK      = "ok"
	SubagentError   = "error"
	SubagentKilled  = "killed"
	SubagentFailed  = "failed"
	SubagentAborted = "aborted"
)
    Subagent result statuses: the child's own, or set by the leader.

const EnvelopeVersion = 1
    EnvelopeVersion is the subagent message envelope version ("v") this package
    reads.

const MetricsVersion = 1
    MetricsVersion is the pi-agent.metrics payload version this package reads.

const SupportedFormatVersion = 3
    SupportedFormatVersion is the pi session format this package reads
    (Header.Version).

const TagsVersion = 1
    TagsVersion is the pi-agent.tags payload version this package reads.


VARIABLES

var (
	// ErrNoHeader is returned when the first line of a file is not a session header.
	ErrNoHeader = errors.New("no session header")
	// ErrUnsupportedFormat is returned for a header whose format is not [SupportedFormatVersion].
	ErrUnsupportedFormat = errors.New("unsupported session format")
)

TYPES

type AgentError struct {
	Message string
	At      time.Time
}
    AgentError is a pi-agent.error entry: an extension could not run.

type CacheMiss struct {
	// Turn is 1-based.
	Turn int `json:"turn"`
	// Expected is what the previous request had cached (its cacheRead + cacheWrite).
	Expected  int `json:"expected"`
	CacheRead int `json:"cacheRead"`
}
    CacheMiss is a request that read less from the prompt cache than expected.

type ContentBlock struct {
	// Type is "text" or "image".
	Type string `json:"type"`
	// Text is the text of a text block.
	Text *string `json:"text,omitempty"`
	// MimeType and Data (base64) are an image block's.
	MimeType *string `json:"mimeType,omitempty"`
	Data     *string `json:"data,omitempty"`
}
    ContentBlock is a text or image block of a tool result.

type Entry struct {
	Type string `json:"type"`
	ID   string `json:"id"`
	// ParentID is the previous entry on its branch; empty for a root entry.
	ParentID  string    `json:"parentId"`
	Timestamp time.Time `json:"timestamp"`
	// CustomType names the extension's entry for "custom" and "custom_message" entries.
	CustomType string `json:"customType,omitempty"`
	// Raw is the entry's whole JSON line.
	Raw json.RawMessage `json:"-"`
}
    Entry is one line after the header: its envelope, and the whole line in Raw.

type EntryError struct {
	ID         string
	Type       string
	CustomType string
	Err        error
}
    EntryError is an entry whose content is invalid for its type.

func (e *EntryError) Error() string

func (e *EntryError) Unwrap() error

type Header struct {
	Type string `json:"type"`
	// Version is pi's session format version; 0 when the file has none (format 1).
	Version   int       `json:"version,omitempty"`
	ID        string    `json:"id"`
	Timestamp time.Time `json:"timestamp"`
	CWD       string    `json:"cwd"`
	// ParentSession is the session file this one was forked from, if any.
	ParentSession string `json:"parentSession,omitempty"`
}
    Header is the first line of a session file. It is not part of the entry
    tree.

func (h Header) FormatVersion() int
    FormatVersion is pi's session format version, 1 when the header has none.

type LineError struct {
	Line int // 1-based
	Err  error
}
    LineError is a line that is not valid JSON or not a valid entry.

func (e *LineError) Error() string

func (e *LineError) Unwrap() error

type Metadata struct {
	SessionID string
	CWD       string
	StartedAt time.Time
	// FormatVersion is pi's session format (header "version").
	FormatVersion int
	// ParentSession is the session file this one was forked from.
	ParentSession *string

	// AgentVersion is the pi-agent release of the last pi-agent.session-version entry in the
	// file; nil for files written by pi-agent 0.11.0 or older, or without pi-agent.
	AgentVersion *string
	// Tags is the last pi-agent.tags entry in the file (tags belong to the whole file).
	Tags *Tags
	// Name is the session name of the last session_info entry in the file; nil when unnamed.
	Name *string

	// Models are the model changes on the current branch, in order.
	Models []ModelChange
	// Errors are the pi-agent.error entries on the current branch, in order.
	Errors []AgentError
}
    Metadata describes a session. Pointers and slices are nil when the file has
    no such entry.

type Metrics struct {
	Tokens  Tokens
	CostUSD float64
	// Turns are agent turns.
	Turns int
	Model ModelMetrics
	// Tools are per tool name.
	Tools       map[string]ToolMetrics
	Compactions int
	// ContextPeakPercent is the highest context use; nil when unknown.
	ContextPeakPercent *float64
	// CacheMisses are requests that read under 95% of the expected cached prefix.
	CacheMisses []CacheMiss
	Samples     Samples

	// Entries is how many metrics entries the branch has.
	Entries int
	// EntryID and At are the newest entry's.
	EntryID string
	At      time.Time
}
    Metrics are a branch's session metrics (src/shared/metrics.ts).
    pi-agent.metrics entries are cumulative along a branch, so the totals are
    the newest entry's; the samples (only what was new at each entry) are those
    of every entry on the branch, oldest first.

type ModelChange struct {
	Provider string
	ModelID  string
	At       time.Time
}
    ModelChange is a model_change entry.

type ModelMetrics struct {
	Calls        int      `json:"calls"`
	TTFTMsP50    *float64 `json:"ttftMsP50"`
	LatencyMsP50 *float64 `json:"latencyMsP50"`
	LatencyMsMax *float64 `json:"latencyMsMax"`
}
    ModelMetrics are model request statistics; the times are nil when there was
    no request.

type Samples struct {
	TTFTMs    []float64 `json:"ttftMs"`
	LatencyMs []float64 `json:"latencyMs"`
	// ToolMs are tool durations per tool name.
	ToolMs map[string][]float64 `json:"toolMs"`
}

