content.text:
}
    Samples are raw measurements in milliseconds, to compute percentiles from.

type Session struct {
	Header  Header
	Entries []Entry
}
    Session is a parsed session file: the header and its entries in file order.

func Parse(r io.Reader) (*Session, error)
    Parse reads a session file. Blank lines are skipped. The first line
    must be a session header (ErrNoHeader) of format SupportedFormatVersion
    (ErrUnsupportedFormat). Every other line must be an entry with a type,
    a unique id and a parentId naming an earlier entry (or null); a line that is
    not is a *LineError.

func ParseFile(path string) (*Session, error)
    ParseFile parses the session file at path.

func (s *Session) Branch() []Entry
    Branch is the current branch: from the root to the leaf, the last entry
    in the file (where pi continues when it loads the file). Entries on other
    branches are left out. Empty when the file has no entries.

func (s *Session) Metadata() (*Metadata, error)
    Metadata reads the session's metadata. Version, tags and name are per file,
    as their extensions define them; models and errors come from the current
    branch. An invalid entry of these types is an *EntryError.

func (s *Session) Metrics() (*Metrics, error)
    Metrics reads the current branch's metrics; nil when it has no
    pi-agent.metrics entry. An invalid entry is an *EntryError; another payload
    version an *UnsupportedVersionError.

func (s *Session) Subagents() ([]Subagent, error)
    Subagents returns the subagents started on the current branch in start
    order. A result message wins over an end record. A result whose start is on
    another branch is left out, as pi-agent does; one whose start is nowhere in
    the file, a duplicate start, or an invalid record is an *EntryError.

func (s *Session) ToolCalls() ([]ToolCall, error)
    ToolCalls returns the tool calls on the current branch in the order the
    model made them, each with its result. An invalid assistant or toolResult
    message, a duplicate call id, or a result without its call earlier on the
    branch is an *EntryError.

type Subagent struct {
	// ID is the agent id, e.g. "a3".
	ID       string
	Scenario string
	// Kind is "task".
	Kind    string
	Task    string
	Project *string
	// RestartOf is the agent this one restarts, e.g. "a2".
	RestartOf *string
	// StartedBy is "model" or "user" (records from before it was recorded: "model").
	StartedBy     string
	StartedAt     time.Time
	TaskMessageID string
	// EntryID is the subagent-start entry.
	EntryID string
	// Result is nil when the branch has none (still running, or the session ended abruptly).
	Result *SubagentResult
}
    Subagent is a subagent started on the current branch, with its result when
    there is one.

type SubagentResult struct {
	ResultID string
	// Status is one of SubagentOK, SubagentError, SubagentKilled, SubagentFailed, SubagentAborted.
	Status  string
	Summary string
	// Reason says why for killed ("user", "leader") and aborted ("leader_exit", "reload", ...).
	Reason     *string
	DetailKind *string
	// Detail is the scenario's result detail; nil when there is none.
	Detail  json.RawMessage
	EndedAt time.Time
	// ChildSessionFile is the subagent's own session file (not parsed here).
	ChildSessionFile *string
	// Delivered is true for a subagent-result message (the model saw it), false for a
	// subagent-end entry.
	Delivered bool
	// EntryID is the entry the result comes from; MessageID its envelope id.
	EntryID   string
	MessageID string
}
    SubagentResult is a subagent's result: a subagent-result message, or else
    a subagent-end entry (recorded at session end, not yet delivered to the
    model).

type Tags struct {
	// Tags in the order given; empty when cleared.
	Tags []string
	// Source is what set them: "flag" (--tags or task.json) or "command" (/tags).
	Source string
	At     time.Time
}
    Tags is a pi-agent.tags entry: the session's whole tag list.

type Tokens struct {
	Input      int `json:"input"`
	Output     int `json:"output"`
	CacheRead  int `json:"cacheRead"`
	CacheWrite int `json:"cacheWrite"`
}
    Tokens are token totals.

type ToolCall struct {
	// ID is the call id the result refers to (toolCallId).
	ID   string
	Name string
	// Args is the arguments object as the model sent it.
	Args json.RawMessage
	// ArgsError is set when the model's arguments were not a valid JSON object (Args is {}).
	ArgsError *string
	// EntryID is the assistant message entry that made the call.
	EntryID  string
	CalledAt time.Time
	// Ref is the tool-ref handle ([tool-ref #N]) of the result; nil without one (session
	// without the tool-ref extension, or no result).
	Ref *int
	// Result is nil when the branch has no result for the call (e.g. pi stopped mid-call).
	Result *ToolResult
}
    ToolCall is a tool call the model made, with its result when there is one.

type ToolMetrics struct {
	Calls  int     `json:"calls"`
	Errors int     `json:"errors"`
	MsP50  float64 `json:"msP50"`
	MsMax  float64 `json:"msMax"`
}
    ToolMetrics are one tool's statistics.

type ToolResult struct {
	// EntryID is the toolResult message entry.
	EntryID string
	IsError bool
	// Content is the result's content blocks, without the tool-ref trailer.
	Content []ContentBlock
	// Details is the tool's structured details; nil when it has none.
	Details json.RawMessage
	At      time.Time
	// DurationMs is how long the tool ran; nil in results from older pi versions.
	DurationMs *float64
}
    ToolResult is the toolResult message of a call.

func (r *ToolResult) Text() string
    Text is the result's text blocks joined with newlines (images left out).

